import type { AuthCandidate, AuthEntry, DataSourceCandidate } from "@speeq/compiler";
import { isSensitiveName } from "@speeq/core/utils";
import { imp, importPath } from "./render.js";

/*
 * Generated sign-in and customer context modules (release 0.12, task 026). Both are server-only
 * files under `.speeq/generated/`, imported by the CLI-owned agent settings, never by client code.
 */

const q = (s: string) => JSON.stringify(s);
const NOTE =
  "// Generated by speeq. Do not edit: delete the first line to take ownership of this file.";

/** Where a candidate stands once the integration engine has acted on it. */
export type BindingStatus =
  | "not-found"
  | "provider-detected"
  | "requires-review"
  | "unsupported"
  | "ready"
  | "generated"
  | "verified";

/** The status to show for an auth candidate before anything is generated. */
export function authStatus(c: AuthCandidate | undefined): BindingStatus {
  if (!c) return "not-found";
  return c.level === "implementation-detected" ? "ready" : c.level;
}

const RETURN_TYPE = "Promise<AgentUser | null>";
const DOC = [
  "/**",
  " * The signed-in user, read from your app's own session on the server for every speeq request.",
  " * The browser can never choose who it is. The id only keeps conversations apart; it is never shown",
  " * to the model. Return null for visitors who are not signed in.",
  " */",
];
const nameOf = (v: string) =>
  `typeof ${v} === "string" && ${v}.trim() ? { profile: { displayName: ${v} } } : {}`;

/**
 * Source of `.speeq/generated/identity.ts` for a detected sign-in system. `file` is the path of the
 * generated file (for relative imports). `profile: false` skips extra provider calls for names.
 */
export function renderIdentity(
  entry: AuthEntry,
  file: string,
  options: { profile?: boolean } = {},
): string {
  const profile = options.profile !== false;
  const head = [NOTE, imp("type { AgentUser }", "speeq/server")];
  let body: string[];
  switch (entry.kind) {
    case "authjs":
    case "nextauth-v4": {
      if (entry.kind === "authjs")
        head.push(imp(`{ ${entry.exportName} as hostAuth }`, importPath(file, entry.file)));
      else {
        head.push(imp("{ getServerSession }", "next-auth"));
        head.push(imp(`{ ${entry.exportName} as hostOptions }`, importPath(file, entry.file)));
      }
      const get =
        entry.kind === "authjs" ? "await hostAuth()" : "await getServerSession(hostOptions)";
      body = [
        `export async function resolveUser(_request: Request): ${RETURN_TYPE} {`,
        `  const session = ${get};`,
        "  const user = session?.user as { id?: unknown; email?: unknown; name?: unknown } | undefined;",
        "  // Auth.js puts `id` on the user only when your callbacks add it; the email is the fallback.",
        '  const id = typeof user?.id === "string" && user.id ? user.id : typeof user?.email === "string" ? user.email : "";',
        "  if (!id) return null;",
        `  return { id${profile ? `, ...(${nameOf("user?.name")})` : ""} };`,
        "}",
      ];
      break;
    }
    case "supabase":
      head.push(imp(`{ ${entry.exportName} as hostClient }`, importPath(file, entry.file)));
      body = [
        `export async function resolveUser(_request: Request): ${RETURN_TYPE} {`,
        "  const supabase = await hostClient();",
        "  // getUser() asks Supabase to validate the session; getSession() would trust the cookie.",
        "  const { data, error } = await supabase.auth.getUser();",
        "  if (error) {",
        "    // A network problem is not a sign-out: throwing lets speeq answer AUTH_UNAVAILABLE.",
        '    if (error.name === "AuthRetryableFetchError") throw error;',
        "    return null;",
        "  }",
        "  const user = data.user;",
        "  if (!user) return null;",
        "  const meta = (user.user_metadata ?? {}) as Record<string, unknown>;",
        '  const name = typeof meta.full_name === "string" ? meta.full_name : meta.name;',
        `  return { id: user.id${profile ? `, ...(${nameOf("name")})` : ""} };`,
        "}",
      ];
      break;
    case "clerk":
      head.push(imp(profile ? "{ auth, currentUser }" : "{ auth }", "@clerk/nextjs/server"));
      body = [
        `export async function resolveUser(_request: Request): ${RETURN_TYPE} {`,
        "  const { userId, orgId } = await auth();",
        "  if (!userId) return null;",
        "  // An organisation switch is a tenant switch: speeq starts a fresh conversation.",
        "  const tenant = orgId ? { tenantId: orgId } : {};",
        ...(profile
          ? [
              "  const user = await currentUser();",
              "  const name = user?.firstName ?? user?.fullName ?? undefined;",
              `  return { id: userId, ...tenant, ...(${nameOf("name")}) };`,
            ]
          : ["  return { id: userId, ...tenant };"]),
        "}",
      ];
      break;
    case "better-auth":
      head.push(imp(`{ ${entry.exportName} as hostAuth }`, importPath(file, entry.file)));
      body = [
        `export async function resolveUser(request: Request): ${RETURN_TYPE} {`,
        "  const session = await hostAuth.api.getSession({ headers: request.headers });",
        "  const user = session?.user;",
        "  if (!user?.id) return null;",
        `  return { id: user.id${profile ? `, ...(${nameOf("user.name")})` : ""} };`,
        "}",
      ];
      break;
  }
  return [...head, "", ...DOC, ...body, ""].join("\n");
}

/** One approved customer context source, ready to render. */
export interface ContextSourceSpec {
  id: string;
  description: string;
  category: DataSourceCandidate["category"];
  /** Endpoint path without parameters, e.g. `/api/cart`. */
  path: string;
  /** Fields the model may see. */
  expose: string[];
  load: "initial" | "on-demand";
  auth: "required" | "optional";
  /** Exposed fields greetings may use. */
  greeting?: string[];
}

/** Why a requested context source cannot be generated. */
export type ContextRefusal =
  | "requires-binding"
  | "no-fields"
  | "sensitive-field"
  | "unknown-field"
  | "auth-not-reviewed"
  | "invalid-id";

/**
 * Turns a discovered candidate and the developer's choices into a spec, or a refusal. Enforced here,
 * not only in the terminal: sensitive fields can never be approved, a source whose endpoint shows no
 * sign-in check needs an explicit review, and endpoints that need parameters need hand-written code.
 */
export function contextSpec(
  c: DataSourceCandidate,
  choice: {
    fields: string[];
    load?: "initial" | "on-demand";
    description?: string;
    /** The developer checked that the endpoint only returns the signed-in user's own data. */
    authReviewed?: boolean;
    greeting?: string[];
  },
): { ok: true; spec: ContextSourceSpec } | { ok: false; reason: ContextRefusal; detail: string } {
  if (c.binding !== "bindable")
    return {
      ok: false,
      reason: "requires-binding",
      detail: `${c.path} needs ${c.requiredInputs.join(", ")}: write a defineContext for it.`,
    };
  if (!/^[a-z][a-z0-9_]{0,40}$/.test(c.id))
    return { ok: false, reason: "invalid-id", detail: c.id };
  const fields = [...new Set(choice.fields)];
  if (fields.length === 0)
    return { ok: false, reason: "no-fields", detail: "Approve at least one field." };
  const known = new Set(c.fields.map((f) => f.name));
  for (const f of fields) {
    const top = f.split(/[.[]/)[0] ?? f;
    if (isSensitiveName(top) || f.split(/[.[\]]+/).some((p) => p && isSensitiveName(p)))
      return {
        ok: false,
        reason: "sensitive-field",
        detail: `${f} looks sensitive and is never shown to the model.`,
      };
    if (known.size > 0 && !known.has(top))
      return {
        ok: false,
        reason: "unknown-field",
        detail: `${f} is not in the response of ${c.path}.`,
      };
  }
  if (c.authEvidence !== "helper-called" && choice.authReviewed !== true)
    return {
      ok: false,
      reason: "auth-not-reviewed",
      detail: `${c.path} shows no sign-in check. Confirm it returns only the signed-in user's own data.`,
    };
  const greeting = (choice.greeting ?? []).filter((g) => fields.includes(g));
  return {
    ok: true,
    spec: {
      id: c.id,
      description: (choice.description ?? `${c.title} of the signed-in customer`)
        .replace(/\s+/g, " ")
        .trim()
        .slice(0, 200),
      category: c.category,
      path: c.path,
      expose: fields,
      load: choice.load ?? "on-demand",
      auth: "required",
      ...(greeting.length ? { greeting } : {}),
    },
  };
}

/**
 * Source of `.speeq/generated/context.ts`. Each source calls the app's own endpoint with the
 * visitor's cookies (the endpoint keeps checking who is asking); only `expose` fields reach the model.
 */
export function renderContext(sources: readonly ContextSourceSpec[]): string {
  if (sources.length === 0)
    return [
      NOTE,
      imp("type { ContextProviderDefinition }", "speeq/server"),
      "",
      "export const contextProviders: ContextProviderDefinition[] = [];",
      "",
    ].join("\n");
  const calls = sources.map(
    (s, i) =>
      `const read${i + 1} = bindEndpoint({ baseUrl, method: "GET", path: ${q(s.path)}, forwardAuth: true, timeoutMs: 1500 });`,
  );
  const items = sources.map((s, i) =>
    [
      "  defineContext({",
      `    id: ${q(s.id)},`,
      `    description: ${q(s.description)},`,
      `    category: ${q(s.category)},`,
      `    auth: ${q(s.auth)},`,
      `    load: ${q(s.load)},`,
      "    output: z.unknown(),",
      `    expose: ${JSON.stringify(s.expose)},`,
      ...(s.greeting?.length ? [`    greeting: ${JSON.stringify(s.greeting)},`] : []),
      `    fetch: (ctx) => read${i + 1}({}, ctx),`,
      "  }),",
    ].join("\n"),
  );
  return [
    NOTE,
    imp("{ bindEndpoint, type ContextProviderDefinition, defineContext }", "speeq/server"),
    imp("{ z }", "zod"),
    "",
    'const baseUrl = process.env.SPEEQ_BASE_URL ?? "http://localhost:3000";',
    ...calls,
    "",
    "export const contextProviders: ContextProviderDefinition[] = [",
    ...items,
    "];",
    "",
  ].join("\n");
}
